import{_ as a}from"./chunks/prontera-compare3.qqNBFt5L.js";import{c as l,Q as i,j as r,m as e}from"./chunks/framework.BPKcPtvA.js";const g=JSON.parse('{"title":"组队与团队副本攻略","description":"RO3组队玩法全攻略，涵盖十人团队副本、百人娱乐副本、队伍职业搭配与副本机制解析。","frontmatter":{"title":"组队与团队副本攻略","description":"RO3组队玩法全攻略，涵盖十人团队副本、百人娱乐副本、队伍职业搭配与副本机制解析。","lastUpdated":true},"headers":[],"relativePath":"guide/party-play.md","filePath":"guide/party-play.md","lastUpdated":1780230058000}'),d={name:"guide/party-play.md"};function o(n,t,s,h,p,u){return i(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="组队与团队副本攻略" tabindex="-1">组队与团队副本攻略 <a class="header-anchor" href="#组队与团队副本攻略" aria-label="Permalink to &quot;组队与团队副本攻略&quot;">​</a></h1><p><img src="'+a+`" alt="RO3 普隆德拉街景"></p><p>RO3延续了RO强社交的MMO核心，组队是游戏后期最重要的玩法。从日常副本到十人团队副本，合理的队伍配置是通关的关键。</p><h2 id="组队基础" tabindex="-1">组队基础 <a class="header-anchor" href="#组队基础" aria-label="Permalink to &quot;组队基础&quot;">​</a></h2><h3 id="组队加成" tabindex="-1">组队加成 <a class="header-anchor" href="#组队加成" aria-label="Permalink to &quot;组队加成&quot;">​</a></h3><ul><li><strong>经验加成</strong>：2人队+10%，3人+15%，4人+20%，5人以上+30%</li><li><strong>掉落加成</strong>：组队状态下稀有掉落概率提升</li><li><strong>职业互补</strong>：不同职业组队有隐藏配合收益</li></ul><h3 id="组队界面" tabindex="-1">组队界面 <a class="header-anchor" href="#组队界面" aria-label="Permalink to &quot;组队界面&quot;">​</a></h3><ul><li>使用快捷键 <code>Ctrl+P</code> 打开组队面板</li><li>可设置自动审批/手动审批</li><li>可按等级范围筛选队员</li><li>可设置目标副本/活动标签</li></ul><h2 id="职业搭配原理" tabindex="-1">职业搭配原理 <a class="header-anchor" href="#职业搭配原理" aria-label="Permalink to &quot;职业搭配原理&quot;">​</a></h2><h3 id="铁三角阵容" tabindex="-1">铁三角阵容 <a class="header-anchor" href="#铁三角阵容" aria-label="Permalink to &quot;铁三角阵容&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>坦克 (Tank) → 抗伤害、拉仇恨</span></span>
<span class="line"><span>    ↕</span></span>
<span class="line"><span>治疗 (Healer) → 回血、驱散、复活</span></span>
<span class="line"><span>    ↕</span></span>
<span class="line"><span>输出 (DPS) → 打伤害、清怪</span></span></code></pre></div><h3 id="推荐队伍配置" tabindex="-1">推荐队伍配置 <a class="header-anchor" href="#推荐队伍配置" aria-label="Permalink to &quot;推荐队伍配置&quot;">​</a></h3><h4 id="_5人小队-适合日常-练级" tabindex="-1">5人小队（适合日常/练级） <a class="header-anchor" href="#_5人小队-适合日常-练级" aria-label="Permalink to &quot;5人小队（适合日常/练级）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>位置</th><th>职业</th><th>数量</th></tr></thead><tbody><tr><td>坦克</td><td>剑士/骑士</td><td>1</td></tr><tr><td>治疗</td><td>服事/祭司</td><td>1</td></tr><tr><td>近战DPS</td><td>盗贼/刺客</td><td>1</td></tr><tr><td>远程DPS</td><td>弓箭手/猎人</td><td>1</td></tr><tr><td>法系DPS</td><td>法师/巫师</td><td>1</td></tr></tbody></table><h4 id="_10人团队-适合团队副本" tabindex="-1">10人团队（适合团队副本） <a class="header-anchor" href="#_10人团队-适合团队副本" aria-label="Permalink to &quot;10人团队（适合团队副本）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>位置</th><th>职业</th><th>数量</th></tr></thead><tbody><tr><td>主坦克</td><td>骑士</td><td>1</td></tr><tr><td>副坦克</td><td>十字军</td><td>1</td></tr><tr><td>主治疗</td><td>祭司</td><td>2</td></tr><tr><td>物理DPS</td><td>刺客/猎人/铁匠</td><td>3</td></tr><tr><td>魔法DPS</td><td>巫师/贤者</td><td>2</td></tr><tr><td>辅助/自由位</td><td>诗人/舞娘/流氓</td><td>1</td></tr></tbody></table><h2 id="十人团队副本" tabindex="-1">十人团队副本 <a class="header-anchor" href="#十人团队副本" aria-label="Permalink to &quot;十人团队副本&quot;">​</a></h2><p>十人团队副本是RO3的核心PvE内容，根据官方预告片和制作人访谈，副本设计强调「沉浸式协作」。</p><h3 id="已知副本-神之境界-暂定名" tabindex="-1">已知副本：神之境界（暂定名） <a class="header-anchor" href="#已知副本-神之境界-暂定名" aria-label="Permalink to &quot;已知副本：神之境界（暂定名）&quot;">​</a></h3><p>在台北电玩展上展示的「神之境界」副本是首次公开的十人副本。</p><p><strong>基本信息</strong>：</p><ul><li><strong>人数要求</strong>：10人</li><li><strong>等级要求</strong>：Lv.60+</li><li><strong>推荐装备</strong>：蓝装以上</li><li><strong>每周限制</strong>：每周1次（赛季刷新）</li></ul><p><strong>BOSS机制特点</strong>：</p><ul><li>融合环境互动（场景机关、地形利用）</li><li>需要精准的职业配合</li><li>特定阶段需要特定职业技能处理</li><li>BOSS有多个阶段形态</li></ul><h3 id="通用副本攻略原则" tabindex="-1">通用副本攻略原则 <a class="header-anchor" href="#通用副本攻略原则" aria-label="Permalink to &quot;通用副本攻略原则&quot;">​</a></h3><ol><li><p><strong>开荒准备</strong></p><ul><li>全员检查装备耐久度</li><li>备足药水（HP大药、SP药、复活叶）</li><li>提前了解BOSS机制（看视频/攻略）</li><li>分配好各位置职责</li></ul></li><li><p><strong>战斗分工</strong></p><ul><li>坦克：拉BOSS面向背对团队</li><li>治疗：保持全员血量在安全线以上</li><li>DPS：优先处理BOSS召唤的小怪/机制</li><li>指挥：指定1人负责喊技能/提醒走位</li></ul></li><li><p><strong>灭团应对</strong></p><ul><li>祭司保留复活术CD用于关键时刻</li><li>灭团后原地等待，别急着回城</li><li>复盘灭团原因，调整战术</li></ul></li></ol><h2 id="百人娱乐副本-百人本" tabindex="-1">百人娱乐副本（百人本） <a class="header-anchor" href="#百人娱乐副本-百人本" aria-label="Permalink to &quot;百人娱乐副本（百人本）&quot;">​</a></h2><p>根据制作人专访，RO3还将推出百人规模的娱乐副本（代号「鲲」）。</p><p><strong>特点</strong>：</p><ul><li>100人同屏战斗</li><li>派对游戏风格（Party Game）</li><li>比十人本更轻松、娱乐性更强</li><li>掉落稀有外观/玩具类道具</li></ul><h2 id="日常副本-旧古城" tabindex="-1">日常副本：旧古城 <a class="header-anchor" href="#日常副本-旧古城" aria-label="Permalink to &quot;日常副本：旧古城&quot;">​</a></h2><p><strong>基本信息</strong>：</p><ul><li>等级要求：Lv.60+</li><li>队伍人数：4人</li><li>每日次数：3次</li><li>经验收益：约800,000/次</li></ul><p><strong>攻略要点</strong>：</p><ul><li>推荐4人满编队吃经验加成</li><li>法师AOE清小怪效率最高</li><li>最后的精英怪需要坦克拉住</li></ul><h2 id="组队礼仪" tabindex="-1">组队礼仪 <a class="header-anchor" href="#组队礼仪" aria-label="Permalink to &quot;组队礼仪&quot;">​</a></h2><h3 id="当队长时" tabindex="-1">当队长时 <a class="header-anchor" href="#当队长时" aria-label="Permalink to &quot;当队长时&quot;">​</a></h3><ul><li>明确标注队伍目标（如「古城日常3缺1」）</li><li>进本前说明掉落分配规则</li><li>合理分配职业配置</li><li>遇到新手耐心指导</li></ul><h3 id="当队员时" tabindex="-1">当队员时 <a class="header-anchor" href="#当队员时" aria-label="Permalink to &quot;当队员时&quot;">​</a></h3><ul><li>进队先打招呼</li><li>确认自己了解副本机制</li><li>及时吃药，别让治疗一直救你</li><li>不要抢坦克的仇恨</li><li>掉落分配遵守规则</li></ul><h2 id="寻找队友渠道" tabindex="-1">寻找队友渠道 <a class="header-anchor" href="#寻找队友渠道" aria-label="Permalink to &quot;寻找队友渠道&quot;">​</a></h2><ol><li><strong>世界频道喊话</strong>：最直接的方式</li><li><strong>公会活动</strong>：公会成员优先组队</li><li><strong>好友列表</strong>：加靠谱的玩家好友</li><li><strong>自动匹配</strong>：如果游戏有匹配系统</li></ol><blockquote><p><strong>核心原则</strong>：一个好队友胜过三个装备好的路人。建立稳定的队友圈子是RO3长期游玩的基石。</p></blockquote>`,43)])])}const q=l(d,[["render",o]]);export{g as __pageData,q as default};
